/**
 * The app's mascot icon, embedded as base64 PNG data rather than read from
 * a file path at runtime — confirmed live that build-resources/ (where
 * these PNGs live in the source tree) does NOT survive packaging except
 * for icon.icns itself (electron-builder's own special-cased handling for
 * that one file, for the app/dock bundle icon — unrelated to and unaffected
 * by this). Embedding the bytes directly sidesteps needing a separate
 * extraResources entry and packaged-vs-dev path resolution for every other
 * place this app wants the mascot at runtime (tray icon, dev-mode dock
 * icon, splash screen). Regenerate by re-running the base64 encode over
 * build-resources/icon.iconset/*.png if the mascot art ever changes.
 */
export const TRAY_ICON_PNG_BASE64 = "";
export const DOCK_ICON_PNG_BASE64 = "";
export const SPLASH_ICON_PNG_BASE64 = "";
